-- PAGES
update pages set title_en='Our mission', subtitle_en='What drives us', body_en='To offer unforgettable travel experiences by showcasing the cultural and natural wealth of Burundi. We are committed to delivering quality services tailored to our clients'' needs, while promoting sustainable and responsible tourism. Our goal is to create memorable moments and to contribute to local economic development.' where slug='mission';
update pages set title_en='Our vision', subtitle_en='Where we are heading', body_en='To become the leader of tourism in Burundi, recognised for our innovation, our expertise and our commitment to excellence. We aim to be the first reference for travellers, fostering authentic interactions between visitors and local communities. Through an inclusive tourism model, we want to promote Burundian heritage while preserving the environment and supporting sustainable development.' where slug='vision';
update pages set title_en='Our values', subtitle_en='Tanganyika e-Bridge International Tours', body_en=E'Authentic hospitality: every traveller is welcomed as a member of the family.\n\nSustainability: we protect the ecosystems and heritage we invite you to discover.\n\nExcellence: service quality and safety guide every one of our services.\n\nInclusion: we work with local communities and value their talents.\n\nInnovation: a digital bridge between Burundi and the world.' where slug='valeurs';
update pages set title_en='Our principles', subtitle_en='The way we work', body_en=E'Transparency in prices and services.\n\nRespect for cultures, people and the environment.\n\nPunctuality and reliability on every itinerary.\n\nConfidentiality and protection of our clients'' data.\n\nWin-win partnership with local providers (PPP: Public Private Partnership).' where slug='principes';
update pages set title_en='SMED LAB', subtitle_en='Laboratory for sustainable tourism solutions and professions', body_en='SMED LAB is TABITO''s innovation lab dedicated to supporting micro, small and medium-sized enterprises in the tourism sector: incubation, training, structuring of offers, digitalisation and access to funding.' where slug='smedlab';
update pages set title_en='TABITO, what is it?', subtitle_en='Tanganyika e-Bridge International Tours', body_en=E'TABITO is a public limited company under Burundian law providing inbound tour operator services. It was founded in September 2023 by a team of multidisciplinary talents dedicated to sustainable tourism, at a time when a new page in the history of the tourism industry was opening.\n\nTABITO works in leisure tourism as well as conference and events tourism, regenerating the new values of the post Covid-19 era.\n\nTABITO is a privileged partner for reaching the great and wonderful destination of Central and East Africa located in the Lake Tanganyika basin, a true platform of new horizons.\n\nTABITO is connected to national sub-destinations including mountain destinations as well as lakeside and beach destinations.\n\nTABITO was born from a deeply human experience, a highly technological ambition and a profoundly hospitable heart.\n\nTABITO is unique: it keeps its clients globally connected through a digital bridge rooted in a refreshing atmosphere carried by the breezes that surf the waters of Lake Tanganyika.' where slug='apropos';
update pages set title_en='Burundi''s tourist sites', subtitle_en='Interactive map', body_en='Explore the sites recorded by our team: national parks, reserves, beaches, waterfalls and places of remembrance.' where slug='accueil-carte';
