update pages set title_en='TABITO, your bridge to Burundi', subtitle_en='About us', body_en=E'TABITO — Tanganyika e-Bridge International Tours is a Burundian travel and tourism promotion agency. We connect international visitors with the natural, cultural and human riches of Burundi, and support local players in promoting their heritage.\n\nFrom the Kibira forest to the beaches of Lake Tanganyika, from sacred drums to living museums, we build authentic, safe and responsible experiences.' where slug='accueil-apropos';
