-- CITIES
update cities set name_en='Bujumbura', summary_en='Economic capital on the shores of Lake Tanganyika.', description_en='Set on the shores of Lake Tanganyika, Bujumbura combines sandy beaches, a lively central market, a living museum, nightlife and sunsets over the DRC mountains.', highlights_en='["Saga and Karera beaches","Bujumbura living museum","Central market and crafts","Sunset over the lake"]'::jsonb where id='d2e90217-1b94-4407-b815-ef7c9b7fad27';
update cities set name_en='Gitega', summary_en='Political capital and cradle of the sacred drum.', description_en='At the heart of the country, Gitega is home to the National Museum and the royal sites that tell the history of the kingdom of Burundi, as well as the sacred drum sanctuaries.', highlights_en='["Gitega National Museum","Gishora drum sanctuary","Royal sites and historic hills"]'::jsonb where id='5cf32c78-d202-4eb2-b950-a0402b7336d0';
update cities set name_en='Ngozi', summary_en='Northern city surrounded by coffee and tea.', description_en='Ngozi is surrounded by coffee and tea plantations, an ideal starting point for Kibira National Park and the region''s hot springs.', highlights_en='["Coffee and tea plantations","Gateway to Kibira National Park","Hot springs"]'::jsonb where id='54b63975-7d1c-4d57-8efb-1016ebf68259';
update cities set name_en='Rumonge', summary_en='Town of fishermen, palm groves and beaches.', description_en='South of Bujumbura, Rumonge lives from fishing and oil palm: quiet beaches, the Vyanda nature sanctuary and the Mugara hot spring.', highlights_en='["Southern lake beaches","Vyanda reserve","Mugara hot spring"]'::jsonb where id='5c96edd9-9025-49c8-8530-1caebb19e63f';
update cities set name_en='Makamba, Rutana and Bururi', summary_en='Burundi''s great tourist south.', description_en='The southern provinces bring together the Karera waterfalls, the Nyakazu fault (the "German breach"), forest reserves and superb hill landscapes.', highlights_en='["Karera waterfalls","Nyakazu fault","Forest reserves","Hill landscapes"]'::jsonb where id='3a18a3fc-b6b9-4b1e-af10-c9d7238f4e27';

